#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, sz;
    int comps;                                  // liczba zbiorów
    DSU(int n) : p(n + 1), sz(n + 1, 1), comps(n) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];                     // kompresja (path halving), bez rekurencji
            x = p[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;               // już w jednym zbiorze
        if (sz[a] < sz[b]) swap(a, b);          // mniejszy pod większy
        p[b] = a;
        sz[a] += sz[b];
        comps--;
        return true;
    }
    bool same(int a, int b) { return find(a) == find(b); }
    int size(int x) { return sz[find(x)]; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    DSU d(n);
    while (q--) {
        char op;
        cin >> op;
        if (op == 'U') {                        // U a b — połącz
            int a, b;
            cin >> a >> b;
            d.unite(a, b);
        } else if (op == 'Q') {                 // Q a b — czy w jednym zbiorze?
            int a, b;
            cin >> a >> b;
            cout << (d.same(a, b) ? "TAK" : "NIE") << '\n';
        } else if (op == 'S') {                 // S a — rozmiar zbioru a
            int a;
            cin >> a;
            cout << d.size(a) << '\n';
        } else {                                // C — liczba zbiorów
            cout << d.comps << '\n';
        }
    }
}

const int MAXN = 1000005;
int p[MAXN], sz[MAXN];

void init(int n) { for (int i = 1; i <= n; i++) { p[i] = i; sz[i] = 1; } }
int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }   // pełna kompresja
bool unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return false;
    if (sz[a] < sz[b]) swap(a, b);
    p[b] = a;
    sz[a] += sz[b];
    return true;
}

