#include <bits/stdc++.h>
using namespace std;
const int MAXN = 100005;
int p[MAXN], sz[MAXN];
long long d[MAXN];                      // d[x] = val(x) - val(p[x])
int find(int x) {
    if (p[x] == x) return x;
    int r = find(p[x]);
    d[x] += d[p[x]];                    // p[x] wskazuje już na r
    p[x] = r;
    return r;
}
int main() {
    int n, q;
    cin >> n >> q;
    for (int i = 1; i <= n; i++) { p[i] = i; sz[i] = 1; d[i] = 0; }
    while (q--) {
        int a, b;
        long long w;                    // x_b - x_a = w
        cin >> a >> b >> w;
        int ra = find(a), rb = find(b);
        if (ra == rb) {
            cout << (d[b] - d[a] == w ? "OK" : "SPRZECZNE") << '\n';
            continue;
        }
        long long dr = w + d[a] - d[b];   // val(rb) - val(ra)
        if (sz[ra] < sz[rb]) { swap(ra, rb); dr = -dr; }
        p[rb] = ra; d[rb] = dr; sz[ra] += sz[rb];
        cout << "OK\n";
    }
}

