struct RollbackDSU {
    vector<int> p, sz;
    vector<int> hist;                       // podpięte korzenie (-1 = nieudane unite)
    RollbackDSU(int n) : p(n + 1), sz(n + 1, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) { while (p[x] != x) x = p[x]; return x; }   // bez kompresji!
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) { hist.push_back(-1); return false; }
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a; sz[a] += sz[b];
        hist.push_back(b);
        return true;
    }
    void rollback() {
        int b = hist.back(); hist.pop_back();
        if (b == -1) return;
        int a = p[b];
        sz[a] -= sz[b];
        p[b] = b;
    }
};

