#include <bits/stdc++.h>
using namespace std;

vector<int> p, sz;
int find(int x) { while (p[x] != x) x = p[x] = p[p[x]]; return x; }
bool unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return false;
    if (sz[a] < sz[b]) swap(a, b);
    p[b] = a; sz[a] += sz[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<array<int, 3>> e(m);               // {waga, a, b} -> sortuje się po wadze
    for (auto& [w, a, b] : e) cin >> a >> b >> w;
    sort(e.begin(), e.end());
    p.resize(n + 1);
    sz.assign(n + 1, 1);
    iota(p.begin(), p.end(), 0);
    long long total = 0;                       // suma wag może przekroczyć int!
    int used = 0;
    for (auto [w, a, b] : e)
        if (unite(a, b)) {
            total += w;
            used++;
        }
    if (used != n - 1) cout << "NIE\n";        // graf niespójny — brak drzewa rozpinającego
    else cout << total << '\n';
}

