#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
vector<int> g[MAXN];
int tin[MAXN], low[MAXN], comp[MAXN], timer_ = 0, ncomp = 0;
bool onStack[MAXN];
vector<int> st;

void tarjan(int v) {
    tin[v] = low[v] = ++timer_;
    st.push_back(v);
    onStack[v] = true;
    for (int u : g[v]) {
        if (!tin[u]) {                         // krawędź drzewowa
            tarjan(u);
            low[v] = min(low[v], low[u]);
        } else if (onStack[u]) {               // krawędź do wierzchołka bieżącej SCC
            low[v] = min(low[v], tin[u]);
        }
    }
    if (low[v] == tin[v]) {                    // v jest korzeniem SCC
        ncomp++;
        while (true) {
            int x = st.back();
            st.pop_back();
            onStack[x] = false;
            comp[x] = ncomp;
            if (x == v) break;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
    }
    for (int v = 1; v <= n; v++)
        if (!tin[v]) tarjan(v);
    vector<int> mn(ncomp + 1, INT_MAX);        // najmniejszy wierzchołek każdej SCC
    for (int v = 1; v <= n; v++) mn[comp[v]] = min(mn[comp[v]], v);
    cout << ncomp << '\n';
    for (int v = 1; v <= n; v++) cout << mn[comp[v]] << ' ';
    cout << '\n';
}

#include <bits/stdc++.h>
using namespace std;

// Kosaraju bez rekurencji — bezpieczny dla n = 10^6
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1), rg(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        rg[b].push_back(a);                    // graf odwrócony
    }
    // 1) kolejność wyjścia (postorder) na g
    vector<int> order, it(n + 1, 0);
    vector<bool> vis(n + 1, false);
    for (int s = 1; s <= n; s++) {
        if (vis[s]) continue;
        vector<int> st = {s};
        vis[s] = true;
        while (!st.empty()) {
            int v = st.back();
            if (it[v] < (int)g[v].size()) {
                int u = g[v][it[v]++];
                if (!vis[u]) { vis[u] = true; st.push_back(u); }
            } else {
                order.push_back(v);
                st.pop_back();
            }
        }
    }
    // 2) na grafie odwróconym, od największego czasu wyjścia
    vector<int> comp(n + 1, 0);
    int c = 0;
    for (int i = n - 1; i >= 0; i--) {
        int s = order[i];
        if (comp[s]) continue;
        c++;
        vector<int> st = {s};
        comp[s] = c;
        while (!st.empty()) {
            int v = st.back(); st.pop_back();
            for (int u : rg[v]) if (!comp[u]) { comp[u] = c; st.push_back(u); }
        }
    }
    vector<int> mn(c + 1, INT_MAX);
    for (int v = 1; v <= n; v++) mn[comp[v]] = min(mn[comp[v]], v);
    cout << c << '\n';
    for (int v = 1; v <= n; v++) cout << mn[comp[v]] << ' ';
    cout << '\n';
}

// Graf kondensacji: wierzchołki = SCC (comp[v] w 1..ncomp), krawędzie między różnymi SCC.
vector<vector<int>> kondensacja(int n, int ncomp, const vector<vector<int>>& g, const vector<int>& comp) {
    vector<vector<int>> dag(ncomp + 1);
    for (int v = 1; v <= n; v++)
        for (int u : g[v])
            if (comp[v] != comp[u]) dag[comp[v]].push_back(comp[u]);
    for (auto& lista : dag) {                  // usuwamy duplikaty krawędzi
        sort(lista.begin(), lista.end());
        lista.erase(unique(lista.begin(), lista.end()), lista.end());
    }
    return dag;
}

