#include <bits/stdc++.h>
using namespace std;

struct TwoSat {
    int n;                                     // liczba zmiennych
    vector<vector<int>> g;
    vector<int> tin, low, comp, st;
    vector<bool> onSt;
    int timer_ = 0, ncomp = 0;
    TwoSat(int n) : n(n), g(2 * n), tin(2 * n, 0), low(2 * n), comp(2 * n), onSt(2 * n, false) {}
    // literał: zmienna i (0..n-1), val = true -> 2i, false -> 2i+1
    static int lit(int i, bool val) { return 2 * i + (val ? 0 : 1); }
    void addClause(int a, int b) {             // (a OR b) na literałach
        g[a ^ 1].push_back(b);                 // ¬a -> b
        g[b ^ 1].push_back(a);                 // ¬b -> a
    }
    void tarjan(int v) {
        tin[v] = low[v] = ++timer_;
        st.push_back(v); onSt[v] = true;
        for (int u : g[v]) {
            if (!tin[u]) { tarjan(u); low[v] = min(low[v], low[u]); }
            else if (onSt[u]) low[v] = min(low[v], tin[u]);
        }
        if (low[v] == tin[v]) {
            ncomp++;
            int x;
            do { x = st.back(); st.pop_back(); onSt[x] = false; comp[x] = ncomp; } while (x != v);
        }
    }
    bool solve(vector<int>& val) {
        for (int v = 0; v < 2 * n; v++) if (!tin[v]) tarjan(v);
        val.assign(n, 0);
        for (int i = 0; i < n; i++) {
            if (comp[2 * i] == comp[2 * i + 1]) return false;   // x i ¬x w jednej SCC
            val[i] = comp[2 * i] < comp[2 * i + 1];             // Tarjan: odwrotny porządek topologiczny
        }
        return true;
    }
};

int main() {
    int n, m;
    cin >> n >> m;                             // zmienne 1..n, klauzule "a b": +x = x, -x = NOT x
    TwoSat ts(n);
    auto conv = [](int x) { return x > 0 ? TwoSat::lit(x - 1, true) : TwoSat::lit(-x - 1, false); };
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        ts.addClause(conv(a), conv(b));
    }
    vector<int> val;
    if (!ts.solve(val)) { cout << "NIE\n"; return 0; }
    cout << "TAK\n";
    for (int i = 0; i < n; i++) cout << val[i] << ' ';
    cout << '\n';
}

