        if (ptr[v] < (int)g[v].size()) st.push_back(g[v][ptr[v]++]);
        else { path.push_back(v); st.pop_back(); }
    }
    if ((int)path.size() != m + 1) { cout << "NIE\n"; return 0; }
    reverse(path.begin(), path.end());
    for (int v : path) cout << v << ' ';
    cout << '\n';
}

