// Hamilton dla małego n: dp[maska][v] = czy da się odwiedzić maskę kończąc w v
int n = 3;
vector<vector<int>> adj = {{0, 1, 0}, {1, 0, 1}, {0, 1, 0}};   // ścieżka 0-1-2
vector<vector<bool>> dp(1 << n, vector<bool>(n, false));
for (int v = 0; v < n; v++) dp[1 << v][v] = true;
for (int mask = 1; mask < (1 << n); mask++)
    for (int v = 0; v < n; v++) if (dp[mask][v])
        for (int u = 0; u < n; u++)
            if (adj[v][u] && !(mask >> u & 1)) dp[mask | 1 << u][u] = true;
bool jest = false;
for (int v = 0; v < n; v++) jest = jest || dp[(1 << n) - 1][v];
cout << jest << '\n';   // 1

#include <bits/stdc++.h>
using namespace std;
int main() {
    int k;
    cin >> k;
    if (k == 1) { cout << "01\n"; return 0; }
    int V = 1 << (k - 1), mask = V - 1;
    vector<int> ptr(V, 0);
    vector<pair<int,int>> st = {{0, -1}};     // (wierzchołek, bit krawędzi wejścia)
    string res;
    while (!st.empty()) {
        auto [v, b] = st.back();
        if (ptr[v] < 2) {
            int bit = ptr[v]++;
            st.push_back({((v << 1) | bit) & mask, bit});
        } else {
            if (b != -1) res += char('0' + b);
            st.pop_back();
        }
    }
    reverse(res.begin(), res.end());
    cout << string(k - 1, '0') + res << '\n';
}

